        public init(weights: Weights, acwrLow: Double, acwrHigh: Double, sleepTargetMin: Double, watchZ: Double) {
            self.weights = weights
            self.acwrLow = acwrLow
            self.acwrHigh = acwrHigh
            self.sleepTargetMin = sleepTargetMin
            self.watchZ = watchZ
        }

        public struct Weights: Codable, Hashable, Sendable {
            public var hrv: Double
            public var rhr: Double
            public var sleep: Double
            public var wellness: Double
            public var load: Double

            public init(hrv: Double, rhr: Double, sleep: Double, wellness: Double, load: Double) {
                self.hrv = hrv
                self.rhr = rhr
                self.sleep = sleep
                self.wellness = wellness
                self.load = load
            }
        }
    }
}

